effect.shader:
vec4 preMultiplicada(vec4 c) { return vec4(c.rgb * c.a, c.a); }

// O filtro linear da GPU, à mão, sobre a camada PRÉ-multiplicada (a textura do AM é assim): os 4 pixels em volta,
// presos à borda como o CLAMP_TO_EDGE.
vec4 camadaNoPonto(sampler2D img, vec2 uv) {
    ivec2 T = textureSize(img, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    ivec2 m = T - 1;
    vec4 c00 = preMultiplicada(texelFetch(img, clamp(a, ivec2(0), m), 0));
    vec4 c10 = preMultiplicada(texelFetch(img, clamp(a + ivec2(1, 0), ivec2(0), m), 0));
    vec4 c01 = preMultiplicada(texelFetch(img, clamp(a + ivec2(0, 1), ivec2(0), m), 0));
    vec4 c11 = preMultiplicada(texelFetch(img, clamp(a + ivec2(1, 1), ivec2(0), m), 0));
    return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

// O mesmo filtro no buffer da camada inteira, mas fora dele é NADA (transparente), e não a borda esticada. Fora do
// buffer a camada não tem pixel: com Recortar abaixo de 1 numa camada do tamanho da tela, a busca passava da borda e
// as fileiras de cima e de baixo viravam listras (relato do Discord, 25/10/2026).
vec4 texelOuNada(sampler2D img, ivec2 a, ivec2 m) {
    if (any(lessThan(a, ivec2(0))) || any(greaterThan(a, m))) return vec4(0.0);
    return preMultiplicada(texelFetch(img, a, 0));
}
vec4 camadaSemBorda(sampler2D img, vec2 uv) {
    ivec2 T = textureSize(img, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    ivec2 m = T - 1;
    vec4 c00 = texelOuNada(img, a, m);
    vec4 c10 = texelOuNada(img, a + ivec2(1, 0), m);
    vec4 c01 = texelOuNada(img, a + ivec2(0, 1), m);
    vec4 c11 = texelOuNada(img, a + ivec2(1, 1), m);
    return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

// A volta da `acCamadaParaTela`: UV da tela → UV do buffer da camada.
vec2 naCamada(vec2 t) {
    vec3 c = inverse(acCamadaParaTela) * vec3(t, 1.0);
    return c.xy / c.z;
}

void main() {
    // O pixel na tela (na tela, a identidade; no filho de grupo, o buffer dele levado à tela do grupo) e, de lá, a
    // coordenada da camada do AM: o retângulo do conteúdo de 0 a 1, com o meio no meio do buffer (o buffer cobre a
    // composição, `acTamanhoDaTela`).
    vec2 conteudo = max(acTamanhoDaCamada, vec2(1e-6));
    vec2 st = 0.5 + (naCamada(acTela(acScreenNorm)) - 0.5) * acTamanhoDaTela / conteudo;
    // O Y do AM cresce para CIMA (a matriz dele inverte o Y da tela) e o do buffer de camada do Nova para baixo
    // (a linha 0 é o topo): sem isto, andam as fileiras erradas e o Ângulo gira ao contrário.
    st.y = 1.0 - st.y;

    // A conta do AM, linha por linha. Os 4 pixels são da imagem renderizada (ver o topo).
    vec2 pixelSize = acEscalaDePixel / vec2(textureSize(inputImg, 0));
    vec2 tiledCoord = st;
    if (vertoffs) {
        tiledCoord.y += step(1., mod(tiledCoord.x, 2.0)) * phase;
    } else {
        tiledCoord.x += step(1., mod(tiledCoord.y, 2.0)) * phase;
    }
    if (mirror) {
        tiledCoord = abs(mod(tiledCoord - vec2(1.0, 1.0), vec2(2.0, 2.0)) - vec2(1.0, 1.0));
    } else {
        tiledCoord = mod(tiledCoord, vec2(1.0, 1.0));
    }
    float a = angle * 0.0174533;
    mat2 rot = mat2(
        cos(a), -sin(a),
        sin(a), cos(a)
    );
    vec2 scaledCoord = tiledCoord;
    scaledCoord -= vec2(0.5, 0.5);
    scaledCoord *= vec2(1.0) / (scale + pixelSize * 4.0);
    scaledCoord.x *= conteudo.x / conteudo.y;
    scaledCoord *= rot;
    scaledCoord.x *= conteudo.y / conteudo.x;
    scaledCoord += vec2(0.5, 0.5);

    // De volta ao buffer da camada e à imagem de entrada: na tela (a entrada é a camada já na tela), pela
    // `acCamadaParaTela` sem a divisão da perspectiva quando ela é afim (como o `acLayerToScreen` do AM; o filho de
    // grupo também vem por aqui desde a 0.622.0, na tela do grupo); numa camada desenhada à parte (o mapa de outro
    // efeito), a própria UV do buffer. O Y volta para baixo.
    vec2 b = 0.5 + (vec2(scaledCoord.x, 1.0 - scaledCoord.y) - 0.5) * conteudo / acTamanhoDaTela;
    // Na tela com a camada inteira à mão: a busca vai ao buffer DELA, e não à camada já na tela. Lá o que a camada
    // tem fora da tela não existe — arrastada para fora, a borda esticava em listras e depois sumia tudo (relato de
    // 22/10/2026). Com a camada inteira na tela, dá o mesmo que antes. Fora do buffer dela, transparente.
    if (acParaTela == mat3(1.0) && acCamadaPropria == 1) {
        vec2 q = 0.5 + (b - 0.5) / max(acFolgaDaCamada, 1e-6);
        // Longe demais o ivec2 do floor estoura: fora de [-1, 2] já é nada.
        bool longe = any(isinf(q)) || any(isnan(q)) || any(lessThan(q, vec2(-1.0))) || any(greaterThan(q, vec2(2.0)));
        vec4 d = longe ? vec4(0.0) : camadaSemBorda(camadaInteira, q);
        fragColor = d.a > 0.0 ? vec4(min(d.rgb / d.a, vec3(1.0)), d.a) : vec4(0.0);
        return;
    }
    vec2 p = b;
    if (acParaTela == mat3(1.0)) {
        vec3 c = acCamadaParaTela * vec3(b, 1.0);
        bool afim = acCamadaParaTela[0].z == 0.0 && acCamadaParaTela[1].z == 0.0 && acCamadaParaTela[2].z == 1.0;
        p = afim ? c.xy : c.xy / c.z;
    }

    // Ponto infinito ou NaN (camada sem tamanho): a GPU decide, como no AM.
    bool foraDaConta = any(isinf(p)) || any(isnan(p));
    vec4 c = foraDaConta ? preMultiplicada(texture(inputImg, p)) : camadaNoPonto(inputImg, p);
    fragColor = c.a > 0.0 ? vec4(min(c.rgb / c.a, vec3(1.0)), c.a) : vec4(0.0);
}
